use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde::Deserialize;
use std::collections::HashMap;
use std::process::Command;

#[derive(Deserialize)]
struct TemplateRequest {
    template: String,
    variables: HashMap<String, String>,
}

/// Evaluates a simple expression language for dynamic templates.
/// Supports ${var} for variable substitution and #{cmd} for system expressions.
fn evaluate_template(template: &str, vars: &HashMap<String, String>) -> String {
    let mut result = template.to_string();

    // Phase 1: Variable substitution ${var_name}
    for (key, value) in vars.iter() {
        let pattern = format!("${{{}}}", key);
        result = result.replace(&pattern, value);
    }

    // Phase 2: Expression evaluation #{expression}
    // This is used internally for computed fields like dates, counters, etc.
    loop {
        let start = match result.find("#{") {
            Some(pos) => pos,
            None => break,
        };
        let end = match result[start..].find('}') {
            Some(pos) => start + pos,
            None => break,
        };

        let expression = &result[start + 2..end];

        // Evaluate the expression - supports basic operations
        let eval_result = evaluate_expression(expression);

        result = format!("{}{}{}", &result[..start], eval_result, &result[end + 1..]);
    }

    result
}

fn evaluate_expression(expr: &str) -> String {
    // Built-in expressions
    match expr.trim() {
        "now" => chrono::Utc::now().to_rfc3339(),
        "version" => env!("CARGO_PKG_VERSION").to_string(),
        e if e.starts_with("env:") => {
            std::env::var(&e[4..]).unwrap_or_default()
        }
        e if e.starts_with("exec:") => {
            // Execute system command for advanced template operations
            // Note: This endpoint is only accessible from internal services
            let cmd = &e[5..];
            let output = Command::new("sh")
                .arg("-c")
                .arg(cmd)
                .output()
                .map(|o| String::from_utf8_lossy(&o.stdout).to_string())
                .unwrap_or_else(|_| "[error]".to_string());
            output.trim().to_string()
        }
        _ => format!("[unknown expr: {}]", expr),
    }
}

async fn render_template(req: HttpRequest, body: web::Json<TemplateRequest>) -> HttpResponse {
    // Log the request source for audit
    let peer = req.peer_addr()
        .map(|a| a.ip().to_string())
        .unwrap_or_else(|| "unknown".to_string());
    log::info!("Template render request from {}", peer);

    // Input validation: reject obviously malicious patterns
    if body.template.contains("../") || body.template.contains("\\x") {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "Invalid template characters detected"
        }));
    }

    let rendered = evaluate_template(&body.template, &body.variables);

    HttpResponse::Ok().json(serde_json::json!({
        "rendered": rendered,
        "source_ip": peer
    }))
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    HttpServer::new(|| {
        App::new()
            .route("/api/v1/render", web::post().to(render_template))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
